// Stern-Brocot Tree — Hierarchy, route: jsx
// Source: stern-brocot-tree
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

/** A node of the tree, held as the continued fraction [a0; a1, a2, ...] it expands to. */
type Fraction = { value: number[]; children?: Fraction[] };

type Node = d3.HierarchyPointNode<Fraction>;
type Link = d3.HierarchyPointLink<Fraction>;

const MARGIN = { top: 22, right: 14, bottom: 22, left: 14 };
const ROW_HEIGHT = 66;
const FONT_SIZE = 10;
/** Half-width of the fraction bar, and the gap links leave around each label. */
const BAR = 5;
const LABEL_GAP = 12;

/**
 * Every positive rational is [a0; a1, ..., ak]; its children are [.., ak + 1] and
 * [.., ak - 1, 2], the smaller first when k is odd.
 */
function buildTree(depth: number): Fraction {
  const root: Fraction = { value: [0, 1] };
  let level = [root];
  for (let i = 0; i < depth; i++) {
    const next: Fraction[] = [];
    for (const parent of level) {
      const k = parent.value.length - 1;
      const head = parent.value.slice(0, k);
      const a: Fraction = { value: [...head, parent.value[k] + 1] };
      const b: Fraction = { value: [...head, parent.value[k] - 1, 2] };
      parent.children = k & 1 ? [a, b] : [b, a];
      next.push(a, b);
    }
    level = next;
  }
  return root;
}

/** Fold a continued fraction back into numerator and denominator. */
function collapse(coefficients: number[]): [number, number] {
  let numerator = 1;
  let denominator = 0;
  for (let i = coefficients.length - 1; i >= 0; i--) {
    [numerator, denominator] = [coefficients[i] * numerator + denominator, numerator];
  }
  return [numerator, denominator];
}

export default function SternBrocotTree({ width }: { width: number }) {
  const innerWidth = Math.max(width - MARGIN.left - MARGIN.right, 0);

  // Deepen only while the widest level still leaves ~14px per leaf for a legible label.
  const depth = Math.max(3, Math.min(6, Math.floor(Math.log2(Math.max(innerWidth, 1) / 14))));
  const innerHeight = depth * ROW_HEIGHT;
  const height = innerHeight + MARGIN.top + MARGIN.bottom;

  const root = useMemo(
    () =>
      d3
        .tree<Fraction>()
        .size([innerWidth, innerHeight])
        .separation(() => 1)(d3.hierarchy(buildTree(depth))),
    [depth, innerWidth, innerHeight]
  );

  const link = useMemo(
    () =>
      d3
        .linkVertical<Link, [number, number]>()
        .source((d) => [d.source.x, d.source.y + LABEL_GAP])
        .target((d) => [d.target.x, d.target.y - LABEL_GAP]),
    []
  );

  if (width === 0) return null;

  const key = (d: Node) => d.data.value.join(',');

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={`Stern-Brocot tree of the positive rationals to depth ${depth}, each node the mediant of its neighbours`}
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`} fontSize={FONT_SIZE}>
        {root.links().map((l) => (
          <path key={key(l.target)} d={link(l) ?? undefined} fill="none" stroke="var(--line)" />
        ))}
        {root.descendants().map((d) => {
          const [numerator, denominator] = collapse(d.data.value);
          return (
            <g key={key(d)} transform={`translate(${Math.round(d.x)},${Math.round(d.y)})`}>
              <title>{`${numerator}/${denominator}`}</title>
              <line x1={-BAR} x2={BAR} stroke="var(--accent)" />
              <text textAnchor="middle" fill="var(--text)">
                <tspan x={0} y={-2.5}>
                  {numerator}
                </tspan>
                <tspan x={0} y={9.5}>
                  {denominator}
                </tspan>
              </text>
            </g>
          );
        })}
      </g>
    </svg>
  );
}
